do $$begin
 if exists(select 1 from regular_pairs p left join public.transport_assets a on a.id=(p.value->>'assetId')::uuid left join public.drivers d on d.id=(p.value->>'driverId')::uuid where a.id is null or d.id is null or a.carrier_id is distinct from d.carrier_id or a.carrier_service_id is distinct from d.carrier_service_id) then raise exception 'HAC50_REGULAR_DRIVER_PAIR_MISMATCH';end if;
end;$$;
update public.drivers d set full_name=p.value->>'displayName' from regular_pairs p where d.id=(p.value->>'driverId')::uuid and d.full_name like '[SYNTHETIC] Driver C%';
insert into public.vehicle_regular_drivers(asset_id,carrier_id,driver_id,version)
select (value->>'assetId')::uuid,(value->>'carrierId')::uuid,(value->>'driverId')::uuid,1 from regular_pairs
on conflict(asset_id) do nothing;
commit;
